#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>       // update check timestamps ("CHECKED n MIN AGO")

#ifdef _WIN32
  #define WIN32_LEAN_AND_MEAN
  #include <windows.h>
  #define DIRECTINPUT_VERSION 0x0800
  #include <dinput.h>
  #include <mmsystem.h>   // timeBeginPeriod for the frame limiter
  #include <mmreg.h>      // WAVEFORMATEXTENSIBLE
  #include <objbase.h>    // CoInitializeEx & friends (LEAN_AND_MEAN drops them)
  #include <mmdeviceapi.h>
  #include <audioclient.h>
  #include <winhttp.h>    // auto-update check; the ~/.curlrc class of attack
                          // does not exist here
  #include <GL/gl.h>
#else
  #include <sys/stat.h>
  #include <unistd.h>
  #include <GL/gl.h>
  #include <EGL/egl.h>
#endif

#ifndef APIENTRY
  #define APIENTRY
#endif

// Fatal errors must be visible even in the -mwindows build (no console).
static void fatal(const char *msg) {
#ifdef _WIN32
  MessageBoxA(NULL, msg, "skill-issue", MB_ICONERROR);
#endif
  fprintf(stderr, "%s\n", msg);
  exit(1);
}

// ---------------------------------------------------------------------------
// GL 3.3 core loader — only what we use beyond the GL 1.1 headers.
// Pointer names match the spec names; nothing here collides with the 1.1
// prototypes in either platform's GL/gl.h (glActiveTexture is avoided: we
// only ever use texture unit 0, which is active by default).
// ---------------------------------------------------------------------------

#ifdef _WIN32  // Linux Mesa gl.h pulls in glext.h which already has these
#include <stddef.h>
typedef char      GLchar;
typedef ptrdiff_t GLsizeiptr;
typedef uint64_t  GLuint64;
typedef struct __GLsync *GLsync;
#endif

#define GL_FRAGMENT_SHADER      0x8B30
#define GL_VERTEX_SHADER        0x8B31
#define GL_COMPILE_STATUS       0x8B81
#define GL_LINK_STATUS          0x8B82
#define GL_ARRAY_BUFFER         0x8892
#define GL_STATIC_DRAW          0x88E4
#define GL_STREAM_DRAW          0x88E0
#define GL_FRAMEBUFFER          0x8D40
#define GL_RENDERBUFFER         0x8D41
#define GL_COLOR_ATTACHMENT0    0x8CE0
#define GL_DEPTH_ATTACHMENT     0x8D00
#define GL_FRAMEBUFFER_COMPLETE 0x8CD5
#define GL_DEPTH_COMPONENT24    0x81A6
#define GL_READ_FRAMEBUFFER     0x8CA8
#define GL_DRAW_FRAMEBUFFER     0x8CA9
#define GL_MAX_SAMPLES          0x8D57
#define GL_CLAMP_TO_EDGE        0x812F
#define GL_R8                   0x8229
#define GL_RED_CORE             0x1903
#define GL_DEPTH_COMPONENT      0x1902
#define GL_CLAMP_TO_BORDER      0x812D
